CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT,"role" TEXT NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Category" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name");
CREATE TABLE "OrganizerProfile" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"displayName" TEXT NOT NULL,"bio" TEXT,CONSTRAINT "OrganizerProfile_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "OrganizerProfile_userId_key" ON "OrganizerProfile"("userId");
CREATE TABLE "Event" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"categoryId" TEXT,"location" TEXT,"latitude" DOUBLE PRECISION,"longitude" DOUBLE PRECISION,"startsAt" TIMESTAMP(3) NOT NULL,"capacity" INTEGER,"organizerId" TEXT,CONSTRAINT "Event_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Tour" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"categoryId" TEXT,"durationMinutes" INTEGER,"meetingPoint" TEXT,"groupSize" INTEGER,"price" INTEGER,"organizerId" TEXT,CONSTRAINT "Tour_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Booking" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT,"tourId" TEXT,"quantity" INTEGER NOT NULL DEFAULT 1,"totalAmount" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Booking_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Ticket" ("id" TEXT NOT NULL,"bookingId" TEXT NOT NULL,"qrCode" TEXT NOT NULL,"uniqueCode" TEXT NOT NULL,CONSTRAINT "Ticket_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Ticket_uniqueCode_key" ON "Ticket"("uniqueCode");
CREATE TABLE "Review" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"eventId" TEXT,"tourId" TEXT,"rating" INTEGER NOT NULL,"comment" TEXT,CONSTRAINT "Review_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"bookingId" TEXT NOT NULL,"provider" TEXT NOT NULL,"amount" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'KES',"status" TEXT NOT NULL,"reference" TEXT,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Payment_bookingId_key" ON "Payment"("bookingId");
ALTER TABLE "OrganizerProfile" ADD CONSTRAINT "OrganizerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Event" ADD CONSTRAINT "Event_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Event" ADD CONSTRAINT "Event_organizerId_fkey" FOREIGN KEY ("organizerId") REFERENCES "OrganizerProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Tour" ADD CONSTRAINT "Tour_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Tour" ADD CONSTRAINT "Tour_organizerId_fkey" FOREIGN KEY ("organizerId") REFERENCES "OrganizerProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_tourId_fkey" FOREIGN KEY ("tourId") REFERENCES "Tour"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Review" ADD CONSTRAINT "Review_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Review" ADD CONSTRAINT "Review_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Review" ADD CONSTRAINT "Review_tourId_fkey" FOREIGN KEY ("tourId") REFERENCES "Tour"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Payment" ADD CONSTRAINT "Payment_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE CASCADE ON UPDATE CASCADE;
